    10
    11    // split the remainder of the document into strings
    12    auto strings = fd.splitIntoStrings();
    13    while (strings.size() < 1) {
    14      strings.emplace_back();
    15    }
    16  #if SIMDJSON_EXCEPTIONS
    17    try {
    18  #endif
    19      simdjson::builtin::ondemand::parser parser;
    20      simdjson::padded_string padded(strings[0]);
    21      auto doc = parser.iterate(padded);
    22      if (doc.error()) {
    23        return 0;
    24      }
    25      for (auto item : doc) {
    26        switch (action) {
    27        case 0: {
    28          simdjson_unused auto x = item.get_string();
    29        } break;
    30        case 1: {
    31          simdjson_unused auto x = item.get_bool();
    32        } break;
    33        case 2: {
    34          simdjson_unused auto x = item.get_array();
    35        } break;
    36        case 3: {
    37          simdjson_unused auto x = item.get_int64();
    38        } break;
    39        case 4: {
    40          simdjson_unused auto x = item.get_double();
    41        } break;
    42        case 5: {
    43          simdjson_unused auto x = item.get_object();
    44        } break;
    45        case 6: {
    46          simdjson_unused auto x = item.get_uint64();
    47        } break;
    48        case 7: {
    49          simdjson_unused auto x = item.get_raw_json_string();
    50        } break;
    51        case 8: {
    52          simdjson_unused auto x = item.is_null();
    53        } break;
    54        case 9: {
    55          simdjson_unused auto x = item.begin();
    56        } break;
    57        case 10: {
    58          simdjson_unused auto x = item.end();
    59        } break;
    60        case 11: {
    61          for (auto e : item) {
    62            simdjson_unused auto x = e.is_null();
    63          }
    64        } break;
    65        default:;
    66        }
    67      }
    68  #if SIMDJSON_EXCEPTIONS
    69    } catch (...) {
    70    }
    71  #endif
    72
    73    return 0;
    74  }
